from fastapi import Depends, HTTPException
from sqlalchemy.orm import sessionmaker, Session

from app.infra.security import oauth2_schema
from app.infra.database import LocalSession
from app.services.auth_service import AuthService

def get_session():
    """Cria a sessão de banco de dados para serem usadas como dependencias"""
    try: 
        session = LocalSession()
        yield session
    finally:
        session.close() 

def auth_service(session: Session = Depends(get_session)):
    """Cria um objeto da classe AuthService"""
    return AuthService(session) 

def verify_access_token(token: str = Depends(oauth2_schema), service: AuthService = Depends(auth_service)):
    """Verifica o acess token enviado em rotas protegidas"""
    try:
        user_id = service.verify_token(token)
        return user_id
    except ValueError as e:
        raise HTTPException(status_code=401, detail=str(e))

def verify_refresh_token(token: str, service: AuthService = Depends(auth_service)):
    """Verifica o refresh token enviado pelo usuário"""
    try:
        user_id = service.verify_refresh_token(token)
        return user_id
    except ValueError as e:
        raise HTTPException(status_code=401, detail=str(e))

from fastapi import APIRouter, Depends, HTTPException
from fastapi.security import OAuth2PasswordRequestForm 
from sqlalchemy.orm import Session

from app.api.dependencies import verify_access_token, auth_service, verify_refresh_token
from app.api.schemas.auth_schemas import LoginSchema 
from app.services.auth_service import AuthService
router = APIRouter()

@router.post("/login")
async def login(schema: LoginSchema, service: AuthService = Depends(auth_service)):
    try:
        access_token, refresh_token = service.login(email=schema.email, password=schema.password)
        return {
            "access_token": access_token,
            "refresh_token": refresh_token,
            "token_type": "Bearer"
        }
    except ValueError as e:
        raise HTTPException(status_code=400, detail="Credenciais Inválidas")

@router.post("/login-form")
async def login_form(schema: OAuth2PasswordRequestForm = Depends(), service: AuthService = Depends(auth_service)):
    try:
        access_token, refresh_token = service.login(email=schema.username, password=schema.password)
        return {
            "access_token": access_token,
            "refresh_token": refresh_token,
            "token_type": "Bearer"
        }
    except ValueError as e:
        raise HTTPException(status_code=400, detail="Credenciais Inválidas")

@router.get("/refresh")
async def use_refresh(user_id: int = Depends(verify_refresh_token), service: AuthService = Depends(auth_service)):
    try:
        access_token = service.generate_access_token(user_id)
        return {
            "access_token": access_token,
            "token_type": "Bearer"
        }
    except ValueError as e:
        raise HTTPException(status_code=401, detail=str(e))

import paho.mqtt.client as mqtt

from app.api.dependencies import get_session
class MqttClient:
    def __init__(self, broker_ip: str, port: int, topic: str, handler, keepalive=60):
        self.__broker_ip = broker_ip
        self.__port = port
        self.__topic = topic
        self.__keepalive = keepalive
        self._handler = handler

        self.__client = mqtt.Client()

        self.__client.on_connect = self._on_connect
        self.__client.on_subscribe = self._on_subscribe
        self.__client.on_message = self._on_message

    def start_connection(self):
        self.__client.connect(host=self.__broker_ip, port=self.__port, keepalive=self.__keepalive)
        self.__client.loop_start()

    def stop_connection(self):
        self.__client.loop_stop()
        self.__client.disconnect()

    def _on_connect(self, client, userdate, flags, rc):
        if rc == 0:
            print("MQTT Client Connected")
            self.__client.subscribe(self.__topic)
        else:
            print(f"Error connecting to the MQTT Client")

    def _on_subscribe(self, client, userdata, mid, granted_qos):
        print(f"Client Subscribed at {self.__topic} QoS: {granted_qos}")

    def _on_message(self, client, userdate, message):
        self._handler.handle(message)

from sqlalchemy.orm import Session

from jose import jwt, JWTError
from datetime import datetime, timedelta, timezone

from app.infra.security import bcrypt_context 
from app.models.user import User
from app.infra.config import Settings

class AuthService:
    def __init__(self, session: Session):
        self._session = session

    # ========================================================
    #                       AUTENTICAÇÃO
    # ========================================================
    def login(self, email: str, password: str) -> tuple[str, str]:
        user = self._session.query(User).filter(User.email == email).first()
        if not user or not bcrypt_context.verify(password, user.password_hash):
            raise ValueError("Credenciais Inválidas")

        access_token = self.generate_access_token(user.id)
        refresh_token = self.generate_refresh_token(user.id)

        return (access_token, refresh_token)

    # ========================================================
    #                 VERIFICAÇÃO DE TOKEN
    # ========================================================
    def verify_token(self, token: str) -> int:
        try:
            info = jwt.decode(token, Settings.SECRET_KEY, Settings.ALGORITHM)
            user_id = info.get("sub")
            if user_id is None:
                raise ValueError("Token Inválido") 
            id = int(user_id)

        except (JWTError, ValueError):
            raise ValueError("Token Inválido")

        user = self._session.query(User).filter(User.id == id).first()
        if not user:
            raise ValueError("Acesso Negado")

        return user.id

    def verify_refresh_token(self, token: str) -> int:
        try:
            info = jwt.decode(token, Settings.SECRET_KEY, Settings.ALGORITHM)

            typ = info.get("typ")
            if typ != "refresh":
                raise ValueError("Token Inválido")

            user_id = info.get("sub")
            if user_id is None:
                raise ValueError("Token Inválido") 
            id = int(user_id)

        except (JWTError, ValueError):
            raise ValueError("Token Inválido")

        user = self._session.query(User).filter(User.id == id).first()

        if not user:
            raise ValueError("Acesso Negado")

        return user.id

    # ========================================================
    #                     GERAÇÃO DE TOKEN
    # ========================================================
    def generate_access_token(self, id: int):
        """Gera token de acesso JWT"""
        return self.__generate_token(id, timedelta(minutes=Settings.ACCESS_TOKEN_EXPIRE_MINUTES), "access")

    def generate_refresh_token(self, id: int):
        """Gera token de recuperação"""
        return self.__generate_token(id, timedelta(minutes=Settings.REFRESH_TOKEN_EXPIRE_MINUTES), "refresh")

    def __generate_token(self, id: int, duration: timedelta, type: str) -> str:
        """Gera token conforme identificador e duração"""
        expired_date = datetime.now(timezone.utc) + duration
        info = {
            "sub": str(id),
            "exp": expired_date,
            "typ": type
        }
        encoded_jwt = jwt.encode(info, Settings.SECRET_KEY, Settings.ALGORITHM)
        return encoded_jwt

